--liquibase formatted sql

-- Conventions for every table:
--   * ids are uuid, generated by Postgres 18's uuidv7() (time-ordered, not guessable).
--   * money is bigint pesewas (GH₵1 = 100 pesewas), never numeric or float.
--   * times are timestamptz, stored in UTC.
--   * enums are text + CHECK with UPPER_CASE values, so adding a value is a one-line migration.

--changeset blinks:0001-set-updated-at splitStatements:false
--comment: Trigger function that keeps updated_at current.
CREATE FUNCTION set_updated_at() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;
--rollback DROP FUNCTION set_updated_at();
